mapper.select:
-- ============================================== -- 功能：未来3天生产订单【组件级明细查询】物料齐套性 -- 核心业务规则：①当日订单仅抢占当日库存，跨日期无抢占 ②订单号小优先占用库存，同单号按主料号排序 ③后天库存计算需扣减未结出库量 ④木桶效应判定整单齐套性 -- ============================================== WITH -- 基础数据：物料BOM清单，按主料+组件维度汇总单台用量 COMMON_BOM AS ( SELECT MAIN_MATERIAL_NO, COMPONENT_MATERIAL_NO, COMPONENT_DESC, SUM(UNIT_USAGE) AS UNIT_USAGE FROM RUOYI.MATERIAL_BOM_IMPORT WHERE DELETED = 0 AND LEVEL_NO = 1 GROUP BY MAIN_MATERIAL_NO, COMPONENT_MATERIAL_NO, COMPONENT_DESC ), -- 基础数据：物料实时库存，按物料号汇总可用库存总量 COMMON_STOCK AS ( SELECT MATERIAL_NO, SUM(AVAILABLE_QUANTITY) AS AVAILABLE_QUANTITY FROM RUOYI.REAL_TIME_STOCK WHERE DELETED = 0 OR DELETED IS NULL GROUP BY MATERIAL_NO ), -- 基础数据：订单未结出库量，按订单+物料维度汇总待出库数量 COMMON_TRACE AS ( SELECT ORDER_NO, MATERIAL_NO, SUM(OUTBOUND_ACCUMULATED) AS OPEN_QUANTITY FROM RUOYI.TRACE_ORDER_DEMAND WHERE DELETED = 0 GROUP BY ORDER_NO, MATERIAL_NO ), -- 基础数据：工单已出库量，按订单+物料维度汇总已领用数量 COMMON_TASK AS ( SELECT order_no, material_no, SUM(quantity) AS outbound_qty FROM RUOYI.WM_DISTRIBUTION_TASK WHERE deleted = 0 GROUP BY order_no, material_no ), -- 【核心修复+核心规则】库存占用量汇总 - 订单优先级递进扣减逻辑 -- 关键逻辑：仅计算当前订单「优先级更高」的订单库存占用，订单号越小优先级越高，同单号主料号越小优先级越高 -- 特殊规则：后天(TRUNC(SYSDATE)+2)的库存需求需扣减未结出库量，明日/大后天不扣减 STOCK_OCCUPY_SUM AS ( SELECT mp2.PRODUCTION_ORDER_NO, mp2.ASSEMBLY_MATERIAL_NO, bom2.COMPONENT_MATERIAL_NO, mp2.SCHEDULED_DATE, SUM( LEAST( CASE WHEN mp2.SCHEDULED_DATE = TRUNC(SYSDATE)+2 THEN mp2.SCHEDULED_QUANTITY * bom2.UNIT_USAGE - COALESCE(TRACE2.OPEN_QUANTITY,0) ELSE mp2.SCHEDULED_QUANTITY * bom2.UNIT_USAGE END, GREATEST(0, COALESCE(stock2.AVAILABLE_QUANTITY,0) - COALESCE(TRACE2.OPEN_QUANTITY,0)) ) ) AS OCCUPY_SUM FROM RUOYI.APS_MAIN_PLAN mp2 JOIN COMMON_BOM bom2 ON mp2.ASSEMBLY_MATERIAL_NO = bom2.MAIN_MATERIAL_NO LEFT JOIN COMMON_STOCK stock2 ON bom2.COMPONENT_MATERIAL_NO = stock2.MATERIAL_NO LEFT JOIN COMMON_TRACE TRACE2 ON mp2.PRODUCTION_ORDER_NO = TRACE2.ORDER_NO AND bom2.COMPONENT_MATERIAL_NO = TRACE2.MATERIAL_NO WHERE mp2.DELETED =0 AND mp2.SCHEDULED_DATE BETWEEN TRUNC(SYSDATE)+1 AND TRUNC(SYSDATE)+3 AND EXISTS ( SELECT 1 FROM RUOYI.APS_MAIN_PLAN mp3 WHERE mp3.DELETED=0 AND mp3.SCHEDULED_DATE = mp2.SCHEDULED_DATE AND mp3.ASSEMBLY_MATERIAL_NO = mp2.ASSEMBLY_MATERIAL_NO AND (mp3.PRODUCTION_ORDER_NO < mp2.PRODUCTION_ORDER_NO OR (mp3.PRODUCTION_ORDER_NO = mp2.PRODUCTION_ORDER_NO AND mp3.ASSEMBLY_MATERIAL_NO < mp2.ASSEMBLY_MATERIAL_NO)) ) GROUP BY mp2.PRODUCTION_ORDER_NO, mp2.ASSEMBLY_MATERIAL_NO, bom2.COMPONENT_MATERIAL_NO, mp2.SCHEDULED_DATE ), -- 主数据整合：订单+物料+库存+占用量 全维度基础数据 -- 关键逻辑：明日/后天/大后天库存独立计算，严格遵循「跨日期无抢占」规则，非当日排产库存为0 BASE_PROD_DATA_DETAIL AS ( SELECT mp.PRODUCTION_ORDER_NO, mp.ASSEMBLY_MATERIAL_NO, mp.MAIN_MATERIAL_DESC, mp.SCHEDULED_DATE, mp.PRODUCTION_WORKSHOP, mp.SCHEDULED_QUANTITY, bom.COMPONENT_MATERIAL_NO, bom.COMPONENT_DESC, bom.UNIT_USAGE, NVL(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, 0) AS REQUIRED_QTY, NVL(stock.AVAILABLE_QUANTITY, 0) AS TOTAL_AVAILABLE_STOCK, NVL(TRACE.OPEN_QUANTITY, 0) AS OPEN_QUANTITY, NVL(task.outbound_qty, 0) AS outbound_qty, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 1 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_TOMORROW, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 2 THEN LEAST((mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE) - COALESCE(TRACE.OPEN_QUANTITY,0), GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_DAY_AFTER_TOMORROW, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 3 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_THIRD_DAY, (CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 1 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END + CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 2 THEN LEAST((mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE) - COALESCE(TRACE.OPEN_QUANTITY,0), GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END + CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 3 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END) AS STOCK_QUANTITY FROM RUOYI.APS_MAIN_PLAN mp JOIN COMMON_BOM bom ON mp.ASSEMBLY_MATERIAL_NO = bom.MAIN_MATERIAL_NO LEFT JOIN COMMON_STOCK stock ON bom.COMPONENT_MATERIAL_NO = stock.MATERIAL_NO LEFT JOIN COMMON_TRACE TRACE ON mp.PRODUCTION_ORDER_NO = TRACE.ORDER_NO AND bom.COMPONENT_MATERIAL_NO = TRACE.MATERIAL_NO LEFT JOIN COMMON_TASK task ON mp.PRODUCTION_ORDER_NO = task.order_no AND bom.COMPONENT_MATERIAL_NO = task.material_no LEFT JOIN STOCK_OCCUPY_SUM s ON mp.PRODUCTION_ORDER_NO = s.PRODUCTION_ORDER_NO AND mp.ASSEMBLY_MATERIAL_NO = s.ASSEMBLY_MATERIAL_NO AND bom.COMPONENT_MATERIAL_NO = s.COMPONENT_MATERIAL_NO AND mp.SCHEDULED_DATE = s.SCHEDULED_DATE WHERE mp.DELETED = 0 AND mp.SCHEDULED_DATE BETWEEN TRUNC(SYSDATE) + 1 AND TRUNC(SYSDATE) + 3 ), -- 组件级核心计算：计算每个组件的可配套数+缺料数+组件齐套状态 -- 关键逻辑：组件可配套数 = (三日库存总和+未结出库量) / 单台用量 向下取整，库存不足则为0 COMPONENT_CORE_CALC_DETAIL AS ( SELECT PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, MAIN_MATERIAL_DESC, SCHEDULED_DATE, PRODUCTION_WORKSHOP, SCHEDULED_QUANTITY, COMPONENT_MATERIAL_NO, COMPONENT_DESC, NVL(UNIT_USAGE,0) AS UNIT_USAGE, NVL(REQUIRED_QTY,0) AS REQUIRED_QTY, STOCK_TOMORROW, STOCK_DAY_AFTER_TOMORROW, STOCK_THIRD_DAY, STOCK_QUANTITY, OPEN_QUANTITY, outbound_qty, GREATEST(0, REQUIRED_QTY - (STOCK_QUANTITY + OPEN_QUANTITY)) AS SHORTAGE_QTY, CASE WHEN (STOCK_QUANTITY + OPEN_QUANTITY) >= REQUIRED_QTY THEN SCHEDULED_QUANTITY WHEN (STOCK_QUANTITY + OPEN_QUANTITY) > 0 THEN FLOOR((STOCK_QUANTITY + OPEN_QUANTITY) / UNIT_USAGE) ELSE 0 END AS COMPLETABLE_SETS, CASE WHEN (STOCK_QUANTITY + OPEN_QUANTITY) >= REQUIRED_QTY THEN '齐套' WHEN (STOCK_QUANTITY + OPEN_QUANTITY) > 0 THEN '齐套' || FLOOR((STOCK_QUANTITY + OPEN_QUANTITY) / UNIT_USAGE) || '套' ELSE '不齐套' END AS KITTING_STATUS FROM BASE_PROD_DATA_DETAIL ), -- 核心逻辑【木桶效应】：订单级齐套性判定唯一依据 -- 关键规则：整单可生产套数 = 该订单下所有组件的最小可配套数，组件短板决定整单产能 MIN_COMPLETABLE_SETS AS ( SELECT PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, SCHEDULED_DATE, MIN(COMPLETABLE_SETS) AS min_completable_sets FROM COMPONENT_CORE_CALC_DETAIL GROUP BY PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, SCHEDULED_DATE ) -- 最终组件级明细查询 SELECT d.PRODUCTION_ORDER_NO, -- 1. 生产订单号 d.ASSEMBLY_MATERIAL_NO, -- 2. 总成物料号 d.MAIN_MATERIAL_DESC, -- 3. 主物料描述 d.SCHEDULED_DATE, -- 4. 排产时间 d.KITTING_STATUS, -- 5. 组件是否齐套 d.PRODUCTION_WORKSHOP, -- 6. 生产车间 d.SCHEDULED_QUANTITY, -- 7. 排产数量 d.COMPONENT_MATERIAL_NO, -- 8. 组件物料号 d.COMPONENT_DESC, -- 9. 组件物料描述 d.UNIT_USAGE, -- 10. 单间物料数量 d.REQUIRED_QTY, -- 11. 所需组件数量 d.STOCK_TOMORROW, -- 12. 明天库存 d.STOCK_DAY_AFTER_TOMORROW, -- 13. 后天库存 d.STOCK_THIRD_DAY, -- 14. 第三天库存 d.STOCK_QUANTITY, -- 15. 总库存数量 d.SHORTAGE_QTY, -- 16. 差额 -- 整单最终齐套状态判定规则 CASE WHEN a.min_completable_sets >= d.SCHEDULED_QUANTITY THEN '齐套' WHEN a.min_completable_sets > 0 THEN '齐套' || a.min_completable_sets || '套' ELSE '不齐套' END AS ASSEMBLY_KITTING_STATUS, -- 17. 订单是否齐套 d.OPEN_QUANTITY AS open_quantity,-- 18. 配送创建数量 d.outbound_qty -- 19. 已出库数量 FROM COMPONENT_CORE_CALC_DETAIL d LEFT JOIN MIN_COMPLETABLE_SETS a ON d.PRODUCTION_ORDER_NO = a.PRODUCTION_ORDER_NO AND d.ASSEMBLY_MATERIAL_NO = a.ASSEMBLY_MATERIAL_NO AND d.SCHEDULED_DATE = a.SCHEDULED_DATE WHERE 1=1 -- 条件1：按生产订单号精确筛选
AND d.PRODUCTION_ORDER_NO = #{params.productionOrderNo}
-- 条件2：按装配物料号精确筛选
AND d.ASSEMBLY_MATERIAL_NO = #{params.assemblyMaterialNo}
-- 条件3：按组件物料号精确筛选
AND d.COMPONENT_MATERIAL_NO = #{params.componentMaterialNo}
-- 条件4：按主物料描述模糊筛选
AND d.MAIN_MATERIAL_DESC LIKE '%' || #{params.mainMaterialDesc} || '%'
-- 条件5：按生产车间精确筛选
AND d.PRODUCTION_WORKSHOP = #{params.productionWorkshop}
-- 条件6：按计划日期范围筛选（传入2个日期时）
AND d.SCHEDULED_DATE BETWEEN #{params.scheduledDate[0]} AND #{params.scheduledDate[1]}
-- 条件7：按计划日期精确筛选（传入1个日期时）
AND d.SCHEDULED_DATE = #{params.scheduledDate[0]}
ORDER BY d.SCHEDULED_DATE, d.PRODUCTION_ORDER_NO, d.COMPONENT_MATERIAL_NO
